    n = len(numbers)
    mean = round(sum(numbers) / n, 2)
    if n % 2 == 1:
        median = round(numbers[n // 2], 2)
    else:
        median = round((numbers[n // 2 - 1] + numbers[n // 2]) / 2, 2)
    return (mean, median)

