from typing import List
import heapq

def top_k_elements(nums: List[int], k: int) -> List[int]:
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    heap = []
    for num, freq in count.items():
        if len(heap) < k:
            heapq.heappush(heap, (freq, num))
        else:
            if freq > heap[0][0]:
                heapq.heappop(heap)
                heapq.heappush(heap, (freq, num))

    result = []
    while heap:
        result.append(heapq.heappop(heap)[1])

    return result[::-1]
```

