from typing import List, Tuple

def find_bridges(n: int, edges: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    bridges = []
    visited = [False] * n
    discovery_time = [-1] * n
    low_value = [-1] * n
    time = 0

    def dfs(node, parent):
        nonlocal time
        visited[node] = True
        discovery_time[node] = low_value[node] = time
        time += 1

        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, node)
