    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    bridges = []

    def dfs(u, time):
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in graph[u]:
            if not visited[v]:
                parent[v] = u
                dfs(v, time)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
