def evaluate_expression(expr: str) -> int:
    import re
    from operator import add, sub, mul, truediv, pow

    # Remove spaces
    expr = expr.replace(" ", "")

    # Define the precedence and associativity of operators
    precedence = {'^': 4, '-': 3, '+': 3, '*': 2, '/': 2}
    left_associative = {'^', '-', '+', '*', '/'}

    # Tokenize the expression
    tokens = re.findall(r'\d+|\+|-|\*|/|\^|\(|\)', expr)

    # Function to apply an operator to the top two elements of the stack
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(add(left, right))
        elif operator == '-':
            values.append(sub(left, right))
        elif operator == '*':
            values.append(mul(left, right))
        elif operator == '/':
            values.append(truediv(left, right))
        elif operator == '^':
            values.append(pow(left, right))

    # Function to evaluate the expression
    def evaluate(tokens):
        operators = []
        values = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            elif token in precedence:
                while (operators and operators[-1] in precedence and
                       ((precedence[operators[-1]] > precedence[token]) or
                        (precedence[operators[-1]] == precedence[token] and token in left_associative))):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '-':
