    if not text:
        return []

    records = []
    current_record = []
    in_quote = False
    escape_next = False

    for char in text:
        if escape_next:
            current_record.append(char)
            escape_next = False
        elif char == '"':
            if in_quote:
                if len(current_record) > 0 and current_record[-1] == '"':
                    current_record[-1] = '"'
                else:
                    in_quote = False
            else:
                in_quote = True
        elif char == ',' and not in_quote:
            records.append(current_record)
