import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = re.compile(r'\s+|[a-zA-Z_]\w*|[0-9]+(\.[0-9]+)?|[+\-*/<>=(),]')
    for match in pattern.finditer(source):
        kind = match.re.pattern
        if kind == r'\s+':
            continue
        text = match.group()
        if kind == r'[a-zA-Z_]\w*':
            kind = 'NAME'
        elif kind == r'[0-9]+(\.[0-9]+)?':
            kind = 'NUMBER'
        elif kind == r'[+\-*/<>=(),]':
            kind = 'OP'
        tokens.append((kind, text))
    return tokens
