            while j < len(lines):
                line += '\n' + lines[j]
                j += 1
                if line.endswith('"') and line[-2] != '"':
                    break
            fields = []
            in_quotes = False
            field = ''
            for char in line:
                if char == '"':
                    if in_quotes:
                        if len(field) > 0 and field[-1] == '"':
                            field = field[:-1]
                        else:
                            in_quotes = False
                    else:
                        in_quotes = True
                elif char == ',' and not in_quotes:
                    fields.append(field)
                    field = ''
                else:
                    field += char
            if len(field) > 0:
                fields.append(field)
            result.append(fields)
            i = j
        else:
            fields = line.split(',')
            result.append(fields)
            i += 1
    return result
