from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = OrderedDict()
    results = []
    keys = []

    for operation in operations:
        if operation[0] == "put":
            key, value = operation[1], operation[2]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif operation[0] == "get":
            key = operation[1]
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(None)

    for key in cache:
        keys.append(key)

    return (results, keys)
