                stack.append(stack.pop() + stack.pop())
        elif parts[0] == 'SUB':
            if len(stack) >= 2:
                stack.append(-stack.pop() + stack.pop())
        elif parts[0] == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
        elif parts[0] == 'DIV':
            if len(stack) >= 2:
                divisor = stack.pop()
                if divisor != 0:
                    stack.append(int(stack.pop() / divisor))
                else:
                    raise ValueError("Division by zero")
    return stack
