def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_ip = len(program)
    if max_ip > 1000:
        raise RuntimeError("Program too long")

    while ip < max_ip:
        instruction = program[ip].split()
        if instruction[0] == "PUSH":
            stack.append(int(instruction[1]))
        elif instruction[0] == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction[0] == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction[0] == "SWAP":
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction[0] == "ADD":
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack.append(stack.pop() + stack.pop())
        elif instruction[0] == "SUB":
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack.append(-stack.pop() + stack.pop())
        elif instruction[0] == "MUL":
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack.append(stack.pop() * stack.pop())
        elif instruction[0] == "JMP":
            ip = int(instruction[1]) - 1
        elif instruction[0] == "JZ":
            if not stack:
                raise ValueError("Stack underflow")
            if stack.pop() == 0:
                ip = int(instruction[1]) - 1
        elif instruction[0] == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction[0]}")
        ip += 1

    return stack
