def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    instruction_count = 0
    max_instruction_count = 1000

    while ip < len(program) and instruction_count < max_instruction_count:
        instruction = program[ip]
        instruction_count += 1

        parts = instruction.split()
        opcode = parts[0]

        if opcode == 'PUSH':
            n = int(parts[1])
            stack.append(n)
        elif opcode == 'POP':
            if not stack:
                raise ValueError("POP from empty stack")
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                raise ValueError("DUP from empty stack")
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                raise ValueError("SWAP with less than 2 elements on stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                raise ValueError("ADD with less than 2 elements on stack")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif opcode == 'SUB':
            if len(stack) < 2:
                raise ValueError("SUB with less than 2 elements on stack")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif opcode == 'MUL':
            if len(stack) < 2:
                raise ValueError("MUL with less than 2 elements on stack")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif opcode == 'JMP':
            t = int(parts[1])
            if t < 0 or t >= len(program):
                raise ValueError("JMP to invalid index")
            ip = t - 1
        elif opcode == 'JZ':
            if len(stack) < 1:
                raise ValueError("JZ with less than 1 element on stack")
            n = stack.pop()
            if n == 0:
                t = int(parts[1])
                if t < 0 or t >= len(program):
                    raise ValueError("JZ to invalid index")
                ip = t - 1
        elif opcode == 'HALT':
            break
        else:
            raise ValueError(f"Unknown opcode: {opcode}")

        ip += 1

    if instruction_count >= max_instruction_count:
        raise RuntimeError("Maximum instruction count exceeded")

    return stack
