from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def solve_two_congruences(r1: int, m1: int, r2: int, m2: int) -> tuple[int, int] | None:
        gcd, x, _ = extended_gcd(m1, m2)
        if (r1 - r2) % gcd != 0:
            return None
        m = m1 * m2 // gcd
        r = (r1 * (m2 // gcd) * x + r2 * (m1 // gcd)) % m
        return r, m

    x, L = congruences[0]
    for r, m in congruences[1:]:
        result = solve_two_congruences(x, L, r, m)
        if result is None:
            return None
        x, L = result

    return x, L
