from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def chinese_remainder_theorem(a: list[int], m: list[int]) -> tuple[int, int]:
        sum = 0
        prod = reduce(lcm, m)
        for n_i, m_i in zip(a, m):
            p = prod // m_i
            sum += n_i * mod_inverse(p, m_i) * p
        return sum % prod, prod

    a = [r % m for r, m in congruences]
    m = [m for _, m in congruences]

    return chinese_remainder_theorem(a, m)

def mod_inverse(a: int, m: int) -> int:
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        # q is quotient
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    # Make x1 positive
    if x1 < 0:
        x1 += m0
    return x1
