def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    dp = [[float('inf')] * cols for _ in range(rows)]
    dp[0][0] = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'X':
                continue
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + 1)
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + 1)

    return dp[-1][-1]
