def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def dfs(x, y, steps):
        if not is_valid(x, y):
            return float('inf')
        if grid[x][y] == 'E':
            return steps
        if grid[x][y] == 'S':
            grid[x] = grid[x][:y] + '.' + grid[x][y+1:]
        min_steps = float('inf')
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                min_steps = min(min_steps, dfs(nx, ny, steps + 1))
        if grid[x][y] == '.':
            grid[x] = grid[x][:y] + 'S' + grid[x][y+1:]
        return min_steps

    start_x, start_y = -1, -1
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_x, start_y = i, j
                break
        if start_x != -1:
            break

    if start_x == -1:
        return -1

    result = dfs(start_x, start_y, 0)
    return result if result != float('inf') else -1
