def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    def multiply_mod(a: list[list[int]], b: list[list[int]], mod: int) -> list[list[int]]:
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def matrix_power(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
        if exp == 0:
            return [[1, 0], [0, 1]]
        elif exp == 1:
            return matrix
        elif exp % 2 == 0:
            half_power = matrix_power(matrix, exp // 2, mod)
            return multiply_mod(half_power, half_power, mod)
        else:
            half_power = matrix_power(matrix, (exp - 1) // 2, mod)
            return multiply_mod(multiply_mod(half_power, half_power, mod), matrix, mod)

    return matrix_power(matrix, exp, mod)
