def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    jobs.sort(key=lambda x: (-x[1], -x[2]))
    slots = [-1] * (max(deadline for _, deadline, _ in jobs) + 1)
    placed_jobs = []

    for name, deadline, profit in jobs:
        for slot in range(deadline, 0, -1):
            if slots[slot] == -1:
                slots[slot] = profit
                placed_jobs.append((slot, name))
                break

    placed_jobs.sort()
    return [name for _, name in placed_jobs]

