            else:
                final_balances[account] += amount
        elif action == 'withdraw':
            account, amount = args
            if account not in final_balances or amount <= 0 or account in frozen_accounts or final_balances[account] - amount < 0:
                failed.append(i)
            else:
                final_balances[account] -= amount
        elif action == 'transfer':
            source, target, amount = args
            if source not in final_balances or target not in final_balances or amount <= 0 or source in frozen_accounts or target in frozen_accounts or final_balances[source] - (amount + 2) < 0:
                failed.append(i)
            else:
                final_balances[source] -= (amount + 2)
                final_balances[target] += amount
        elif action == 'freeze':
            account, = args
            if account not in final_balances:
