    stock = defaultdict(int)
    waiting = defaultdict(deque)

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
            while waiting[item] and waiting[item][0][1] <= stock[item]:
                order_item, order_quantity = waiting[item].popleft()
                stock[item] -= order_quantity
                if order_quantity > stock[item]:
                    waiting[item].appendleft((order_item, order_quantity - stock[item]))
                    stock[item] = 0
                    break
        elif kind == 'order':
            waiting[item].append((item, quantity))

    return dict(stock), list(waiting.items())

