def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]:
    order_counts = {}
    pending_orders = []

    for event_type, order_id, quantity in events:
        if event_type == "ORDER":
            if order_id in order_counts:
                order_counts[order_id] += quantity
            else:
                order_counts[order_id] = quantity
        elif event_type == "CANCEL":
            if order_id in order_counts:
                if order_counts[order_id] > quantity:
                    order_counts[order_id] -= quantity
                elif order_counts[order_id] == quantity:
                    del order_counts[order_id]
                else:
                    raise ValueError("Cancel quantity exceeds order quantity")
            else:
                raise ValueError("Order not found for cancellation")
        elif event_type == "PENDING":
            pending_orders.append((order_id, quantity))

    return order_counts, pending_orders
