def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    executed = 0

    while ip < len(program) and executed < 1000:
        instruction = program[ip]
        parts = instruction.split()
        op = parts[0]

        if op == 'PUSH':
            stack.append(int(parts[1]))
        elif op == 'POP':
            if not stack:
                return None
            stack.pop()
        elif op == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                return None
            stack.append(-stack.pop() + stack.pop())
        elif op == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            ip = int(parts[1]) - 1
        elif op == 'JZ':
            if not stack:
                return None
            if stack.pop() == 0:
                ip = int(parts[1]) - 1
            else:
                ip += 1
        else:
            return None

        ip += 1
        executed += 1

    return stack if ip >= len(program) else None
