def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' for c in number):
        raise ValueError("Invalid input")

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    number = number.lower()
    is_negative = number.startswith('-')
    if is_negative:
        number = number[1:]

    # Convert from from_base to decimal
    decimal_number = 0
    for char in number:
        if char.isdigit():
            value = int(char)
        else:
            value = digits.index(char)
        if value >= from_base:
            raise ValueError("Invalid digit for base")
        decimal_number = decimal_number * from_base + value

    # Convert from decimal to to_base
    if decimal_number == 0:
        return '0'
    result = ''
    while decimal_number > 0:
        result = digits[decimal_number % to_base] + result
        decimal_number //= to_base

    return '-' + result if is_negative else result
