    if decimal_number == 0:
        return '0'

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []

    while decimal_number > 0:
        result.append(digits[decimal_number % to_base])
        decimal_number //= to_base

    if is_negative:
        result.append('-')

    return ''.join(reversed(result))
