            ip = int(instruction[1]) - 1
        elif instruction[0] == 'JZ':
            if not stack:
                return None
            if stack.pop() == 0:
                ip = int(instruction[1]) - 1
        ip += 1

    if len(stack) > max_instructions:
        return None

    return stack[::-1]
