def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(d not in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'[:from_base] for d in number):
        raise ValueError("Invalid input")

    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    # Convert from from_base to decimal
    decimal_number = 0
    for i, digit in enumerate(reversed(number)):
        if '0' <= digit <= '9':
            value = ord(digit) - ord('0')
        else:
            value = ord(digit.lower()) - ord('a') + 10
        decimal_number += value * (from_base ** i)

    # Convert from decimal to to_base
    if decimal_number == 0:
        return '0'
    digits = []
    while decimal_number > 0:
        remainder = decimal_number % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(remainder - 10 + ord('a')))
        decimal_number //= to_base

    result = ''.join(reversed(digits))
    if is_negative:
        result = '-' + result

    return result
