    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' for c in number):
        raise ValueError("Invalid input")

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    number = number.lower()
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    value = 0
    for char in number:
        if '0' <= char <= '9':
            digit = ord(char) - ord('0')
        else:
            digit = ord(char) - ord('a') + 10
        if digit >= from_base:
            raise ValueError("Invalid digit for the given base")
        value = value * from_base + digit

    if value == 0:
        return '0'

    result = ''
    while value > 0:
        digit = value % to_base
        if digit < 10:
            result = chr(ord('0') + digit) + result
        else:
            result = chr(ord('a') + digit - 10) + result
        value //= to_base

    if is_negative:
        result = '-' + result

    return result
