import re

def parse_jobs(text: str) -> list[dict]:
    jobs = []
    job_pattern = re.compile(r'Job ID: (\d+), Title: (.+), Location: (.+), Salary: (\$\d+)')
    for match in job_pattern.finditer(text):
        job = {
            'job_id': int(match.group(1)),
            'title': match.group(2),
            'location': match.group(3),
            'salary': int(match.group(4).replace('$', ''))
        }
        jobs.append(job)
    return jobs

