import operator
import re

def evaluate_expression(expression: str) -> float:
    if not expression:
        raise ValueError("Empty expression")

    # Remove spaces
    expression = expression.replace(" ", "")

    # Check for balanced parentheses
    if expression.count("(") != expression.count(")"):
        raise ValueError("Unbalanced parentheses")

    # Define supported operators
    ops = {
        "+": operator.add,
        "-": operator.sub,
        "*": operator.mul,
        "/": operator.truediv,
        "**": operator.pow,
    }

    # Define a function to evaluate a single token
    def evaluate_token(token):
        if token in ops:
            return ops[token]
        elif token.startswith("-"):
            return -float(token[1:])
        else:
            return float(token)

    # Split the expression into tokens
    tokens = re.split(r'(\D)', expression)

    # Evaluate the expression using the Shunting Yard algorithm
    output_queue = []
    operator_stack = []
    for token in tokens:
        if token.isdigit() or (token.startswith("-") and token[1:].isdigit()):
            output_queue.append(evaluate_token(token))
        elif token in ops:
            while (operator_stack and operator_stack[-1] in ops and
                   ops[token].__name__ != "**"):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == "(":
            operator_stack.append(token)
        elif token == ")":
            while operator_stack[-1] != "(":
                output_queue.append(operator_stack.pop())
            operator_stack.pop()

    while operator_stack:
        output_queue.append(operator_stack.pop())

    # Evaluate the postfix expression
    stack = []
    for token in output_queue:
        if callable(token):
            b = stack.pop()
            a = stack.pop()
            stack.append(token(a, b))
        else:
            stack.append(token)

    return stack[0]
