import operator
import re

def evaluate_expression(expression: str) -> float:
    if not expression:
        raise ValueError("Empty expression")

    # Remove spaces
    expression = expression.replace(" ", "")

    # Check for balanced parentheses
    if expression.count("(") != expression.count(")"):
        raise ValueError("Unbalanced parentheses")

    # Define operators
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow
    }

    # Define unary minus
    def unary_minus(x):
        return -x

    # Tokenize the expression
    tokens = re.findall(r'\d+\.\d+|\d+|\(|\)|\+|\-|\*|\/|\*\*', expression)

    # Evaluate the expression
    def evaluate(tokens):
        stack = []
        op_stack = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit() or (token.startswith('-') and i == 0):
                stack.append(float(token))
            elif token == '(':
                op_stack.append(token)
            elif token == ')':
                while op_stack and op_stack[-1] != '(':
                    apply_operator(op_stack, stack)
                op_stack.pop()  # Remove '('
            elif token in ops:
                while (op_stack and op_stack[-1] in ops and
                       ops[op_stack[-1]].__name__ != 'unary_minus'):
                    apply_operator(op_stack, stack)
                op_stack.append(token)
            elif token == '-':
                if i == 0 or tokens[i-1] in ops:
                    stack.append(unary_minus)
                else:
                    apply_operator(op_stack, stack)
            i += 1
        while op_stack:
            apply_operator(op_stack, stack)
        return stack[0]

    def apply_operator(op_stack, stack):
        op = op_stack.pop()
        if op == '-':
            b = stack.pop()
            a = stack.pop()
            stack.append(unary_minus(b))
        else:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[op](a, b))

    try:
        result = evaluate(tokens)
    except ZeroDivisionError:
        raise
    except Exception:
        raise ValueError("Invalid expression")

    return result
