import operator

def matches_filter(expression: str, record: dict) -> bool:
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '%': operator.mod,
        '**': operator.pow,
        '==': operator.eq,
        '!=': operator.ne,
        '<': operator.lt,
        '>': operator.gt,
        '<=': operator.le,
        '>=': operator.ge,
        'and': operator.and_,
        'or': operator.or_,
        'not': operator.not_
    }

    def eval_expr(expr):
        if expr.isdigit():
            return int(expr)
        elif expr.replace('.', '', 1).isdigit():
            return float(expr)
        elif expr in record:
            return record[expr]
        elif expr in ops:
            return ops[expr]
        else:
            raise ValueError(f"Invalid expression or variable: {expr}")

    def parse_and_eval(tokens):
        stack = []
        for token in tokens:
            if token in ops:
                while stack and stack[-1] != '(' and ops[token].__priority__ <= ops[stack[-1]].__priority__:
                    right = stack.pop()
                    left = stack.pop()
                    stack.append(ops[stack.pop()](left, right))
                stack.append(token)
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1] != '(':
                    right = stack.pop()
                    left = stack.pop()
                    stack.append(ops[stack.pop()](left, right))
                stack.pop()
            else:
                stack.append(eval_expr(token))
        while stack:
            right = stack.pop()
            left = stack.pop()
            stack.append(ops[stack.pop()](left, right))
        return stack[0]

    tokens = expression.split()
    return parse_and_eval(tokens)
