import math
from operator import add, sub, mul, truediv, pow

def evaluate_formula(formula: str, x: float) -> float:
    operators = {'+': add, '-': sub, '*': mul, '/': truediv, '**': pow}
    functions = {'sqrt': math.sqrt, 'abs': abs, 'sin': math.sin, 'cos': math.cos}

    def evaluate(tokens):
        stack = []
        for token in tokens:
            if token in operators:
                b = stack.pop()
                a = stack.pop()
                stack.append(operators[token](a, b))
            elif token in functions:
                arg = stack.pop()
                stack.append(functions[token](arg))
            else:
                stack.append(float(token))
        return stack[0]

    tokens = formula.replace('x', str(x)).replace('**', '^').split()
    try:
        return evaluate(tokens)
    except ZeroDivisionError:
        raise
    except Exception:
        raise ValueError("Invalid formula")
