import math
import operator

def evaluate_formula(formula: str, x: float) -> float:
    def secure_eval(formula):
        operators = {
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.truediv,
            '**': operator.pow,
            'sqrt': math.sqrt,
            'abs': abs,
            'sin': math.sin,
            'cos': math.cos
        }
        tokens = formula.split()
        stack = []
        for token in tokens:
            if token in operators:
                b = stack.pop()
                a = stack.pop()
                result = operators[token](a, b)
                stack.append(result)
            elif token == '-':
                if stack and isinstance(stack[-1], (int, float)):
                    stack[-1] = -stack[-1]
                else:
                    b = stack.pop()
                    a = stack.pop()
                    result = operators[token](a, b)
                    stack.append(result)
            else:
                stack.append(float(token))
        return stack[0]

    try:
        return secure_eval(formula)
    except (ZeroDivisionError, ValueError, SyntaxError):
        raise ValueError("Invalid formula")
