    i = 0
    while i < len(formula):
        if formula[i].isdigit() or formula[i] == '.':
            j = i
            while j < len(formula) and (formula[j].isdigit() or formula[j] == '.'):
                j += 1
            tokens.append(float(formula[i:j]))
            i = j
        elif formula[i] in operators:
            tokens.append(operators[formula[i]])
            i += 1
        elif formula[i] in functions:
            j = i + 1
            while j < len(formula) and formula[j].isalpha():
                j += 1
            tokens.append(functions[formula[i:j]])
            i = j
        elif formula[i] == '(':
            tokens.append(formula[i])
            i += 1
        elif formula[i] == ')':
            tokens.append(formula[i])
            i += 1
        else:
            raise ValueError("Invalid character in formula")

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '-':
            values.append(-right)
        else:
            values.append(operator(left, right))

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3, '-': 4}
        return precedence[op1] > precedence[op2]

    values = []
    operators_stack = []

    for token in tokens:
        if isinstance(token, float):
            values.append(token)
        elif isinstance(token, function):
            operators_stack.append(token)
        elif token == '(':
            operators_stack.append(token)
        elif token == ')':
            while operators_stack and operators_stack[-1] != '(':
                apply_operator(operators_stack, values)
            operators_stack.pop()
        else:
            while (operators_stack and operators_stack[-1] != '(' and
                   greater_precedence(operators_stack[-1], token)):
                apply_operator(operators_stack, values)
            operators_stack.append(token)

    while operators_stack:
        apply_operator(operators_stack, values)

    if len(values) != 1:
        raise ValueError("Invalid formula")

    return values[0]
