        if not all(re.match(r'^[a-zA-Z0-9-]+$', label) for label in labels[:-1]) or not re.match(r'^[a-zA-Z]+$', labels[-1]):
            return False

    # Check for valid port
    if ':' in host:
        port = host.split(':')[1]
        if port and int(port) != 443:
