    # Check if the URL starts with https://
    if not url.startswith(('http://', 'https://')):
        return False

    # Check for any backslashes, spaces, or control characters
    if re.search(r'[\\ \x00-\x1F\x7F]', url):
        return False

    # Extract the host part of the URL
    host_part = url.split('//')[1].split('/')[0]

    # Check if the host ends with a dot
    if host_part.endswith('.'):
        host_part = host_part[:-1]

    # Split the host into labels
    labels = host_part.split('.')

    # Check if the host is localhost or ends with .localhost
    if host_part in ('localhost', 'localhost.'):
        return False

    # Check if the host is a valid DNS name
    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False
        if label[0] == '-' or label[-1] == '-':
            return False

    # Check if the port is present and not 443
    if ':' in host_part:
        port = host_part.split(':')[1]
        if port != '443':
            return False

