import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Normalize IPv6 addresses
        if ':' in ip_str:
            ip_str = ipaddress.IPv6Address(ip_str).compressed

        # Check if the IP is a valid IPv4 or IPv6 address
        ip = ipaddress.ip_address(ip_str)

        # Check if the IP is a private, loopback, link-local, multicast, unspecified, reserved, or documentation address
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_documentation:
            return False

        # Check if the IP is in the shared address space 100.64.0.0/10
        if ip.version == 4 and ip.is_private and ip.network_address == ipaddress.ip_address('100.64.0.0'):
            return False

        # Check if the IP is the IPv4 broadcast address
        if ip.version == 4 and ip.is_broadcast:
            return False

        return True
    except (ipaddress.AddressValueError, ValueError):
        return False
