def search_orders(conn: sqlite3.Connection, status: Optional[str] = None, min_total: Optional[str] = None) -> List[Tuple]:
    query = "SELECT id, customer, status, total FROM orders ORDER BY id ASC"
    params: List = []

    if status is not None:
        query += " WHERE status = ?"
        params.append(status)

    if min_total is not None:
        if status is not None:
            query += " AND total >= ?"
        else:
            query += " WHERE total >= ?"
        params.append(float(min_total))

    cursor = conn.cursor()
    cursor.execute(query, params)
    return cursor.fetchall()

